import{z as l,x as s,o as r,c as p,q as i,j as o,D as t,d as e,s as B,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"显示原理","description":"","frontmatter":{"title":"显示原理","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/revelation-principle.md","filePath":"econ/revelation-principle.md","lastUpdated":1791413859000}'),d={name:"econ/revelation-principle.md"};function h(c,a,C,m,D,F){const n=s("Mermaid");return r(),p("div",null,[a[2]||(a[2]=i('<h1 id="显示原理" tabindex="-1">显示原理 <a class="header-anchor" href="#显示原理" aria-label="Permalink to &quot;显示原理&quot;">​</a></h1><div class="epigraph"><p>任何通过博弈实施的激励相容结果，都可以由一个说真话的直接机制复制；设计者只需在直接机制上优化。</p><footer>—— Myerson, Incentive Compatibility and the Bargaining Problem, Econometrica, 1979；Gibbard, Econometrica, 1973；Dasgupta, Hammond and Maskin, RES, 1979</footer></div><p><a href="/econ/incomplete-contracts">上一课</a>（不完全合同）。在给定的合同形式里写 IC。缺口是：合同可以任意弯——先报价、再抽签、再谈判、再发信号。是否必须在这个大空间里搜？显示原理说不必。把「均衡里人们实际在做的」收成「把类型报给计划者，由计划者执行原均衡结果」，说真话本身是均衡。本课钉这一归约，信息课序还有可实施、VCG、虚拟价值与 GS 四课；GDP 核算课程在宏观另起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>机制是一套博弈规则：消息空间 \\(M_i\\)，结果函数 \\(g(m)\\)。给定先验，BNE 或占优策略均衡给出结果映射 \\(\\theta\\mapsto x\\)。设计者关心的是这个映射（配置、支付），不是消息的名字。<a href="/econ/screening-rent">筛选菜单</a>、拍卖、公共品的林达尔表，都是某 \\(M\\) 上的机制。</p><p>直接机制：\\(M_i=\\Theta_i\\)，\\(g\\) 直接吃报告。显示原理：若某间接机制有一个均衡实施了映射 \\(x(\\theta)\\)，则存在直接机制，使说真话是均衡，且实施同一 \\(x(\\theta)\\)。证明是复制：计划者问类型，模拟各人在原机制均衡里会发的消息，再执行 \\(g\\)。偏离直接机制等于在原机制里发了均衡外消息，不会更好。</p><p><span class="marginnote">直觉类比：间接机制像一台带密码规则的翻译机，均衡策略就是每类人的「密码本」。显示原理说：把密码本交给计划者，每人只报自己属于哪一类，由计划者代查密码、代按按钮——结果一模一样，而谎报不会带来原均衡里没有的好处。</span></p><h3 id="显示不是「人人自动诚实」" tabindex="-1">显示不是「人人自动诚实」 <a class="header-anchor" href="#显示不是「人人自动诚实」" aria-label="Permalink to &quot;显示不是「人人自动诚实」&quot;">​</a></h3><p>原理不说真话是占优，也不说实施无成本。它说搜索可以限在直接、真话 IC 的机制类。真话 IC 仍可能很紧，信息租金、数量扭曲、不可能定理都还在。Gibbard–Satterthwaite 正是在直接机制上证明：非独裁的社会选择，在广泛定义域上无法占优策略实施。</p><p><span class="marginnote">常见误区：初学者容易把显示原理读成「人们天生诚实」或「说真话总是占优」。实际上真话只是均衡——是设计者用信息租金把 IC 约束买下来的结果；租金给不够，谎报立刻回来，不可能定理也一条都没被取消。</span></p><p><span class="marginnote">贝叶斯显示原理用 BNE；占优策略显示原理更强，对应优势策略激励相容。拍卖里，Myerson 的最优拍卖在直接机制上对虚拟估值积分，不必枚举所有间接叫价规则。</span></p><p>原理假定设计者能承诺 \\(g\\)。若事后可以再谈，代理人会预见到被抽租，间接的分阶段机制可能严格优于一次显示。本课在承诺站住的基准里收束。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：不完全信息、准线性或一般偏好，共同先验（贝叶斯版）。结论：最优机制 = 在激励相容、可行、参与约束下选直接机制。委托–代理的「合同 \\(w(x)\\)」已经是直接的：代理人不报类型（道德风险无类型时），或报类型再配行动（混合模型）。有类型时，先用显示收成 \\(q(\\theta),t(\\theta)\\)，再优化——筛选课其实已经用了本课的结论。</p><p>公共品：林达尔价要真实 MRS，显示原理把「任意揭示博弈」收成「报 MRS」，但 IC 会挡住第一最佳（Green–Laffont 等），回到<a href="/econ/theory-of-second-best">次优</a>与租金。</p>',15)),(r(),o(A,null,{default:t(()=>[B(n,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20IND%5B%22%E4%BB%BB%E6%84%8F%E9%97%B4%E6%8E%A5%E6%9C%BA%E5%88%B6%20%2B%20%E5%9D%87%E8%A1%A1%22%5D%20--%3E%20DIR%5B%22%E7%9B%B4%E6%8E%A5%E6%9C%BA%E5%88%B6%EF%BC%9A%E6%8A%A5%20%CE%B8%22%5D%0A%20%20DIR%20--%3E%20TT%5B%22%E8%AF%B4%E7%9C%9F%E8%AF%9D%E6%98%AF%E5%9D%87%E8%A1%A1%22%5D%0A%20%20TT%20--%3E%20OPT%5B%22%E5%8F%AA%E5%9C%A8%20IC%20%E7%9B%B4%E6%8E%A5%E6%9C%BA%E5%88%B6%E4%B8%8A%E4%BC%98%E5%8C%96%22%5D%0A%20%20OPT%20--%3E%20STOP%5B%22%E4%BF%A1%E6%81%AF%E8%AF%BE%E5%BA%8F%E5%88%B0%20GS%20%E6%89%8D%E6%94%B6%E6%9D%9F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("归约能成立，是因为计划者可以内部模拟均衡策略 \\(\\sigma_i(\\theta_i)\\)。代理人没有新的偏离空间：他能对计划者谎报的，不过是假装自己是另一类型，而这正是原均衡里「用另一类型的策略」已经比较过的。故 IC 不等式在直接机制上不多也不少。"),E("a",{href:"/econ/screening-rent"},"筛选"),e("的菜单、"),E("a",{href:"/econ/principal-agent"},"委托–代理"),e("的 \\(w(x)\\)，其实都已经是直接机制；本课只是把「为什么不必再搜更弯的规则」写成定理。")],-1)),(r(),o(A,null,{default:t(()=>[B(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%BB%A3%E7%90%86%E4%BA%BA%E7%9C%9F%E5%AE%9E%E7%B1%BB%E5%9E%8B%20%CE%B8%22%5D%20--%3E%20B%5B%22%E5%90%91%E8%AE%A1%E5%88%92%E8%80%85%E6%8A%A5%E5%91%8A%20%CE%B8%CC%82%22%5D%0A%20%20B%20--%3E%20C%5B%22%E8%AE%A1%E5%88%92%E8%80%85%E4%BB%A3%E6%9F%A5%E5%8E%9F%E5%9D%87%E8%A1%A1%E7%AD%96%E7%95%A5%20%CF%83(%CE%B8%CC%82)%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%9B%BF%E4%BB%96%E5%8F%91%E5%87%BA%E5%AF%B9%E5%BA%94%E6%B6%88%E6%81%AF%E5%B9%B6%E6%89%A7%E8%A1%8C%20g%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%BE%97%E5%88%B0%E4%B8%8E%E5%8E%9F%E5%9D%87%E8%A1%A1%E7%9B%B8%E5%90%8C%E7%9A%84%E9%85%8D%E7%BD%AE%20x(%CE%B8)%22%5D%0A%20%20A%20--%3E%20F%5B%22%E8%8B%A5%E8%B0%8E%E6%8A%A5%20%CE%B8%CC%82%E2%80%B2%20%E6%9B%B4%E5%A5%BD%EF%BC%9F%22%5D%0A%20%20F%20--%3E%20G%5B%22%E7%AD%89%E4%BB%B7%E4%BA%8E%E5%9C%A8%E5%8E%9F%E6%9C%BA%E5%88%B6%E5%8F%91%E5%9D%87%E8%A1%A1%E5%A4%96%E6%B6%88%E6%81%AF%22%5D%0A%20%20G%20--%3E%20H%5B%22%E5%8E%9F%E5%9D%87%E8%A1%A1%E5%B7%B2%E6%8E%92%E9%99%A4%20%E2%86%92%20%E8%AF%B4%E7%9C%9F%E8%AF%9D%E6%98%AF%E5%9D%87%E8%A1%A1%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p>原理不创造信息。隐藏行动若发生在报告之后，仍要结果合同；显示只收「报告」这一层。动态、多次报告，有动态显示原理，承诺与重新谈判会破坏「一次报完」，本课不展开。信息课序到此工具收齐：BNE、PBE、隐藏类型、隐藏行动、IC 规划。核算课程在信息课序收束后另起，不再把 GDP 当成某个机制的直接显示。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>显示原理要求设计者能承诺执行 \\(g\\)，不能事后改约。重新谈判、有限承诺，间接机制可能严格优于被显示过的直接机制。多重均衡时，「某一个均衡可显示」不保证所有均衡都说真话；实施理论要更强的条件（Maskin 单调等）。占优策略比贝叶斯更少机制可用。</p><p><span class="marginnote">为什么重要：承诺一旦站不住，整套归约就塌了——代理人预见到事后会被重新谈判「抽租」，一开始就不肯说真话，这时弯弯绕的分阶段间接机制反而更优。应用显示原理前先问一句：设计者真能保证按公布的 g 执行吗？</span></p><p>也不要把显示原理写成宏观或公司金融的资本结构；那些后课程用别的摩擦。本课把博弈与信息主干的工具收齐：配置问题从此变成带 IC 的规划。</p><p>贝叶斯版用 BNE，占优策略版用优势策略 IC。后者更少机制，但执行不依赖先验是否被共同持有。</p><p>后课默认：谈机制设计，先写直接机制与真话 IC；再问承诺是否站得住。</p><h3 id="不可能性不被原理取消" tabindex="-1">不可能性不被原理取消 <a class="header-anchor" href="#不可能性不被原理取消" aria-label="Permalink to &quot;不可能性不被原理取消&quot;">​</a></h3><p>Gibbard–Satterthwaite 在广泛定义域上排除占优策略的非独裁社会选择。贝叶斯 IC 更宽，Myerson 最优拍卖走这一层：先把所有叫价规则收成 IC 的 \\(Q_i(\\theta),t_i(\\theta)\\)，再对虚拟估值优化。选哪一层 IC，是承诺与先验，不是显示原理能决定的。Myerson–Satterthwaite 同样：双边交易不能既有效又自愿又预算平衡；间接机制救不了直接机制做不到的事。柠檬关闭、竞争保险无均衡，都与可行 IC 配置集太小一致。</p><p>无承诺、合谋、事后谈判会让间接机制严格优于被显示过的直接机制。GDP 三种算法的核算课程在信息课序收束后另起，不再把国民核算当成某个直接机制的真话显示。</p><p><span class="marginnote">筛选菜单、委托–代理的 \\(w(x)\\) 其实都已经是直接机制；本课只把「不必再搜更弯的规则」写成定理。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>间接机制的均衡结果可由说真话的直接机制复制。</li><li>设计者只在 IC 直接机制上优化；不消除租金与不可能。</li><li>需要承诺执行；重新谈判可打破归约。</li><li>信息课序在 Gibbard–Satterthwaite 收束，核算课序另起。</li><li>出处：Gibbard, 1973；Dasgupta–Hammond–Maskin, <em>RES</em> 1979；Myerson, <em>Econometrica</em> 1979。</li></ul>',13))])}const f=l(d,[["render",h]]);export{b as __pageData,f as default};
